const k = game.macros.find(m => m.getFlag?.("world","dicebox")?.stableId === "dbx:central-lodge:macro:runtime");
if (!k) return;
const t = event?.data?.token ?? event?.token ?? null;
const a = t?.actor ?? null;
return await k.execute({actor:a,token:t,event,speaker:{dicebox:{"contract":"dicebox-discovery/v1","action":"notice","trigger":"TOKEN_ENTER","noticeKey":"c1.shrine-incompleteness","dc":6,"stage2Skill":"Investigation","successMessage":"<p>The shrine is incomplete by design rather than by simple damage. Two fitted ritual positions are conspicuously empty.</p>","followUp":"Suggested follow-up: Investigation.","failure":"silent","oncePerCharacter":true,"autoAwardItem":false,"criticalClueFallback":"Deliberate inspection of the shrine reveals the two missing ritual placements."}}});

