const k = game.macros.find(m => m.getFlag?.("world","dicebox")?.stableId === "dbx:central-lodge:macro:runtime");
if (!k) return;
const t = event?.data?.token ?? event?.token ?? null;
const a = t?.actor ?? null;
const result = await k.execute({actor:a,token:t,event,speaker:{dicebox:{"contract":"dicebox-region-behavior/v1","action":"gate","trigger":"TOKEN_ENTER","statePath":"puzzles.c1.shrineResolved","requirements":[{"type":"state","path":"puzzles.c1.covenantSealInstalled","equals":true},{"type":"state","path":"puzzles.c1.ceremonialCenserInstalled","equals":true}],"set":[{"path":"puzzles.c1.c2Unlocked","value":true}],"incompleteMessage":"<p>The shrine remains incomplete. Two prepared positions in the altar arrangement still need their proper ritual objects.</p>","successMessage":"<p>With the covenant seal and ceremonial censer restored to the shrine, the altar mechanism settles into alignment and the inner threshold releases.</p>"}}});
if (!["PASS","ALREADY_RESOLVED"].includes(result?.status)) return result;
const gms = Array.from(game.users ?? []).filter(u => u.active && u.isGM).sort((a,b)=>a.id.localeCompare(b.id));
if (gms[0]?.id !== game.user?.id) return result;
const l = game.journal.get("xhlXv6CCH34HVga3");
const s = l?.getFlag?.("world","dicebox")?.state ?? {};
if (foundry.utils.getProperty(s,"puzzles.c1.c2Unlocked") !== true) return result;
const w = game.scenes.get("EDdktL7VUihbpKe9")?.walls.get("oVJ6kFkHMxu4EKF8");
if (w && w.ds !== CONST.WALL_DOOR_STATES.OPEN) await w.update({ds:CONST.WALL_DOOR_STATES.OPEN});
return result;

